import React, { useState, useEffect } from 'react';
import ReactDOM from 'react-dom/client';

const BLOQUEIOS_MANUAIS = ['2025-11-20T13:00', '2025-11-20T13:30'];
const HORARIO_INICIO = 13;
const HORARIO_FIM = 18;
const DURACAO_REUNIAO = 30;
const EMAILJS_SERVICE_ID = 'service_tuk62ie';
const EMAILJS_TEMPLATE_ID = 'template_59t268h';
const EMAILJS_CLIENT_TEMPLATE_ID = 'template_i07vwop';
const EMAILJS_PUBLIC_KEY = 'B4Y9trQ0fvuOdWMvV';
const GOOGLE_SHEETS_SCRIPT_URL = 'https://script.google.com/macros/s/AKfycbxIvNcmLhc1BtAeKnSXsEuudgiAtNLGxL7PoEnR-GoMtF0owMKRr-iC5wV66QIR0xnv8A/exec';

const getBrasiliaDate = () => {
  return new Date(new Date().toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
};

const Header = () => (
  <header style={{ background: 'linear-gradient(135deg, #134a22 0%, #1a6b2f 100%)' }}>
    <div className="container mx-auto px-4 py-10 flex flex-col items-center text-center">
      <h1 className="text-3xl md:text-4xl font-bold text-white">PATITOUR AGENDA FÁCIL</h1>
    </div>
  </header>
);

const LoadingSpinner = () => (
  <div className="flex justify-center items-center py-16">
    <div className="animate-spin rounded-full h-16 w-16 border-t-4 border-b-4 border-green-700"></div>
  </div>
);

const DateSelector = ({ selectedDate, onDateChange }) => {
  const [currentMonth, setCurrentMonth] = useState(new Date());

  const daysInMonth = new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1, 0).getDate();
  const firstDay = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), 1).getDay();

  const days = [];

  for (let i = 0; i < firstDay; i++) {
    days.push(<div key={`e-${i}`} className="h-12"></div>);
  }

  for (let day = 1; day <= daysInMonth; day++) {
    const date = new Date(currentMonth.getFullYear(), currentMonth.getMonth(), day);
    const today = getBrasiliaDate();
    today.setHours(0, 0, 0, 0);

    const disabled = date.getDay() === 0 || date < today;
    const selected = date.toDateString() === selectedDate.toDateString();

    days.push(
      <button
        key={day}
        onClick={() => !disabled && onDateChange(date)}
        disabled={disabled}
        className={`h-12 w-12 mx-auto flex items-center justify-center rounded-full text-sm font-semibold transition-all
          ${selected ? 'bg-green-700 text-white shadow-lg scale-110' : disabled ? 'text-gray-300 cursor-not-allowed' : 'text-gray-700 hover:bg-green-100 hover:text-green-800'}
        `}
      >
        {day}
      </button>
    );
  }

  const prevMonth = () => {
    const newMonth = new Date(currentMonth);
    newMonth.setMonth(currentMonth.getMonth() - 1);
    setCurrentMonth(newMonth);
  };

  const nextMonth = () => {
    const newMonth = new Date(currentMonth);
    newMonth.setMonth(currentMonth.getMonth() + 1);
    setCurrentMonth(newMonth);
  };

  return (
    <div className="mb-8">
      <div className="flex items-center mb-4">
        <div className="h-px bg-gray-300 flex-1"></div>
        <h2 className="text-sm font-bold text-gray-400 uppercase tracking-wider px-4">1. Escolha uma data</h2>
        <div className="h-px bg-gray-300 flex-1"></div>
      </div>
      <div className="bg-white rounded-2xl border border-gray-200 shadow-sm max-w-lg mx-auto overflow-hidden">
        <div className="flex items-center justify-between px-6 py-4 bg-gray-50 border-b">
          <button onClick={prevMonth} className="p-2 hover:bg-gray-200 rounded-lg transition-colors text-gray-600">❮</button>
          <span className="text-lg font-bold text-gray-800 capitalize">
            {currentMonth.toLocaleDateString('pt-BR', { month: 'long' })} De {currentMonth.getFullYear()}
          </span>
          <button onClick={nextMonth} className="p-2 hover:bg-gray-200 rounded-lg transition-colors text-gray-600">❯</button>
        </div>
        <div className="grid grid-cols-7 gap-2 p-6 text-center">
          {['DOM', 'SEG', 'TER', 'QUA', 'QUI', 'SEX', 'SÁB'].map(d => (
            <div key={d} className="text-xs font-bold text-gray-400 uppercase mb-2">{d}</div>
          ))}
          {days}
        </div>
      </div>
    </div>
  );
};

const TimeSlots = ({ slots, onSlotSelect, isLoading }) => {
  if (isLoading) return <LoadingSpinner />;

  return (
    <div className="mt-8">
      <div className="flex items-center mb-6">
        <div className="h-px bg-gray-300 flex-1"></div>
        <h2 className="text-sm font-bold text-gray-400 uppercase tracking-wider px-4">2. Escolha um horário</h2>
        <div className="h-px bg-gray-300 flex-1"></div>
      </div>
      {slots.length > 0 ? (
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 max-w-3xl mx-auto">
          {slots.map(slot => (
            <button
              key={slot.toISOString()}
              onClick={() => onSlotSelect(slot)}
              className="border-2 border-green-700 text-green-700 font-bold py-4 rounded-xl hover:bg-green-700 hover:text-white transition-all transform hover:scale-105"
            >
              {slot.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
            </button>
          ))}
        </div>
      ) : (
        <p className="text-center text-gray-500 bg-gray-100 p-8 rounded-xl max-w-md mx-auto">
          Sem horários disponíveis para esta data.
        </p>
      )}
    </div>
  );
};

const BookingForm = ({ selectedSlot, onBook, onBack }) => {
  const [info, setInfo] = useState({ name: '', school: '', email: '', whatsapp: '' });
  const [emailError, setEmailError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);

  const validateEmail = (email) => {
    const regex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return regex.test(email);
  };

  const handleEmailChange = (e) => {
    const value = e.target.value;
    setInfo({ ...info, email: value });

    if (value && !validateEmail(value)) {
      setEmailError('Por favor, insira um e-mail válido');
    } else {
      setEmailError('');
    }
  };

  const formatWhatsApp = (value) => {
    const numbers = value.replace(/\D/g, '');

    if (numbers.length <= 2) {
      return numbers;
    } else if (numbers.length <= 7) {
      return `(${numbers.slice(0, 2)}) ${numbers.slice(2)}`;
    } else if (numbers.length <= 11) {
      return `(${numbers.slice(0, 2)}) ${numbers.slice(2, 7)}-${numbers.slice(7)}`;
    }
    return `(${numbers.slice(0, 2)}) ${numbers.slice(2, 7)}-${numbers.slice(7, 11)}`;
  };

  const handleWhatsAppChange = (e) => {
    const formatted = formatWhatsApp(e.target.value);
    setInfo({ ...info, whatsapp: formatted });
  };

  const handleSubmit = () => {
    if (isSubmitting) return;

    if (!info.name || !info.school || !info.email || !info.whatsapp) {
      alert('Por favor, preencha todos os campos!');
      return;
    }

    if (!validateEmail(info.email)) {
      setEmailError('Por favor, insira um e-mail válido');
      alert('Por favor, insira um e-mail válido!');
      return;
    }

    const numbersOnly = info.whatsapp.replace(/\D/g, '');
    if (numbersOnly.length < 11) {
      alert('Por favor, insira um WhatsApp válido com DDD (11 dígitos)!');
      return;
    }

    setIsSubmitting(true);
    onBook(info);
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="text-center mb-8">
        <h2 className="text-3xl font-bold text-gray-800 mb-2">Quase lá!</h2>
        <p className="text-gray-600">Preencha seus dados para finalizar o agendamento.</p>
      </div>

      <div className="mb-8 bg-green-50 p-6 rounded-2xl border-2 border-green-200">
        <div className="flex items-start gap-4">
          <div className="bg-green-700 rounded-xl p-3 flex-shrink-0">
            <svg className="w-8 h-8 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z" />
            </svg>
          </div>
          <div className="flex-1">
            <p className="text-green-800 font-bold text-sm uppercase tracking-wide mb-1">Agendamento para:</p>
            <p className="text-gray-800 font-bold text-xl capitalize">
              {selectedSlot.toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long' })}
            </p>
            <p className="text-green-700 font-bold text-2xl mt-1">
              {selectedSlot.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}
            </p>
          </div>
        </div>
      </div>

      <div className="space-y-5">
        <div>
          <label className="block text-gray-500 text-xs font-bold uppercase tracking-wide mb-2">Nome Completo</label>
          <input
            required
            placeholder="Ex: João Silva"
            className="w-full p-4 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-green-700 focus:border-transparent transition-all"
            value={info.name}
            onChange={e => setInfo({ ...info, name: e.target.value })}
            disabled={isSubmitting}
          />
        </div>

        <div>
          <label className="block text-gray-500 text-xs font-bold uppercase tracking-wide mb-2">Escola / Empresa</label>
          <input
            required
            placeholder="Nome da sua instituição"
            className="w-full p-4 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-green-700 focus:border-transparent transition-all"
            value={info.school}
            onChange={e => setInfo({ ...info, school: e.target.value })}
            disabled={isSubmitting}
          />
        </div>

        <div>
          <label className="block text-gray-500 text-xs font-bold uppercase tracking-wide mb-2">E-mail</label>
          <input
            required
            type="email"
            placeholder="seu@email.com"
            className={`w-full p-4 border-2 rounded-xl focus:ring-2 focus:ring-green-700 transition-all ${
              emailError ? 'border-red-500' : 'border-gray-200 focus:border-transparent'
            }`}
            value={info.email}
            onChange={handleEmailChange}
            disabled={isSubmitting}
          />
          {emailError && (
            <p className="text-red-500 text-sm mt-1">{emailError}</p>
          )}
        </div>

        <div>
          <label className="block text-gray-500 text-xs font-bold uppercase tracking-wide mb-2">WhatsApp</label>
          <input
            required
            placeholder="(00) 00000-0000"
            maxLength={15}
            className="w-full p-4 border-2 border-gray-200 rounded-xl focus:ring-2 focus:ring-green-700 focus:border-transparent transition-all"
            value={info.whatsapp}
            onChange={handleWhatsAppChange}
            disabled={isSubmitting}
          />
          <p className="text-gray-400 text-xs mt-1">Digite apenas números, a formatação é automática</p>
        </div>

        <div className="flex gap-4 pt-4">
          <button
            type="button"
            onClick={onBack}
            className="w-1/3 bg-gray-200 text-gray-700 p-4 rounded-xl font-bold hover:bg-gray-300 transition-colors disabled:opacity-50"
            disabled={isSubmitting}
          >
            Voltar
          </button>
          <button
            type="button"
            onClick={handleSubmit}
            className="flex-1 bg-green-700 text-white p-4 rounded-xl font-bold shadow-lg hover:bg-green-800 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            disabled={isSubmitting}
          >
            {isSubmitting ? 'Processando...' : 'Confirmar'}
          </button>
        </div>
      </div>
    </div>
  );
};

const Confirmation = ({ event, onNew }) => {
  return (
    <div className="text-center p-6 max-w-2xl mx-auto">
      <div className="relative w-32 h-32 mx-auto mb-8">
        <div className="absolute inset-0 bg-green-100 rounded-full opacity-50 animate-ping"></div>
        <div className="relative w-32 h-32 bg-green-100 rounded-full flex items-center justify-center">
          <svg className="w-16 h-16 text-green-700" fill="currentColor" viewBox="0 0 20 20">
            <path fillRule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clipRule="evenodd" />
          </svg>
        </div>
      </div>

      <h2 className="text-4xl font-bold text-gray-800 mb-2">Solicitação Recebida!</h2>
      <p className="text-xl text-green-700 font-semibold mb-8">Muito obrigado, {event.clientInfo.name.split(' ')[0]}!</p>

      <div className="bg-gray-50 p-8 rounded-2xl border-2 border-gray-200 text-left space-y-4 mb-8">
        <div className="flex justify-between items-center border-b border-gray-200 pb-3">
          <span className="text-gray-500 text-sm font-bold uppercase tracking-wide">Data</span>
          <span className="text-gray-800 font-bold">{event.date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit', year: 'numeric' })}</span>
        </div>
        <div className="flex justify-between items-center border-b border-gray-200 pb-3">
          <span className="text-gray-500 text-sm font-bold uppercase tracking-wide">Horário</span>
          <span className="text-gray-800 font-bold text-xl">{event.date.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' })}</span>
        </div>
        <div className="flex justify-between items-center">
          <span className="text-gray-500 text-sm font-bold uppercase tracking-wide">Escola / Empresa</span>
          <span className="text-gray-800 font-semibold">{event.clientInfo.school}</span>
        </div>
      </div>

      <div className="bg-blue-50 border-2 border-blue-200 p-6 rounded-2xl mb-8">
        <p className="text-gray-700 leading-relaxed">
          Um e-mail de confirmação foi enviado para{' '}
          <strong className="text-gray-900">{event.clientInfo.email}</strong>. 
          Entraremos em contato via WhatsApp em breve.
        </p>
      </div>

      <button 
        onClick={onNew} 
        className="inline-flex items-center gap-2 text-green-700 font-bold text-lg hover:text-green-800 transition-colors group"
      >
        Fazer novo agendamento
        <svg className="w-5 h-5 transform group-hover:translate-x-1 transition-transform" fill="none" stroke="currentColor" viewBox="0 0 24 24">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M17 8l4 4m0 0l-4 4m4-4H3" />
        </svg>
      </button>
    </div>
  );
};

function App() {
  const [selectedDate, setSelectedDate] = useState(null);
  const [availableSlots, setAvailableSlots] = useState([]);
  const [selectedSlot, setSelectedSlot] = useState(null);
  const [confirmedEvent, setConfirmedEvent] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [bookedSlots, setBookedSlots] = useState({});

  useEffect(() => {
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/@emailjs/browser@3/dist/email.min.js';
    script.onload = () => {
      window.emailjs.init(EMAILJS_PUBLIC_KEY);
      console.log('✅ EmailJS inicializado');
    };
    document.head.appendChild(script);

    const today = getBrasiliaDate();
    if (today.getHours() >= HORARIO_FIM) {
      today.setDate(today.getDate() + 1);
    }
    while (today.getDay() === 0) {
      today.setDate(today.getDate() + 1);
    }
    handleDateChange(today);
  }, []);

  const handleDateChange = async (date) => {
    setSelectedDate(date);
    setSelectedSlot(null);
    setIsLoading(true);

    await new Promise(resolve => setTimeout(resolve, 300));

    const slots = [];
    let current = new Date(date);
    current.setHours(HORARIO_INICIO, 0, 0, 0);
    const limit = new Date(date);
    limit.setHours(HORARIO_FIM, 0, 0, 0);
    const now = getBrasiliaDate();

    const dateKey = date.toDateString();
    const bookedForDate = bookedSlots[dateKey] || [];

    while (current < limit) {
      const sig = `${current.getFullYear()}-${current.getMonth()}-${current.getDate()}-${current.getHours()}-${current.getMinutes()}`;
      const iso = new Date(current.getTime() - (current.getTimezoneOffset() * 60000))
        .toISOString()
        .slice(0, 16);

      const blocked = BLOQUEIOS_MANUAIS.includes(iso) || bookedForDate.includes(sig);

      if (current > now && !blocked) {
        slots.push(new Date(current));
      }

      current = new Date(current.getTime() + DURACAO_REUNIAO * 60000);
    }

    setAvailableSlots(slots);
    setIsLoading(false);
  };

  const handleBook = async (info) => {
    if (!selectedSlot) return;

    setIsLoading(true);

    const sig = `${selectedSlot.getFullYear()}-${selectedSlot.getMonth()}-${selectedSlot.getDate()}-${selectedSlot.getHours()}-${selectedSlot.getMinutes()}`;

    const dateKey = selectedSlot.toDateString();
    setBookedSlots(prev => ({
      ...prev,
      [dateKey]: [...(prev[dateKey] || []), sig]
    }));

    console.log('📅 Iniciando agendamento...', info);

    if (GOOGLE_SHEETS_SCRIPT_URL) {
      try {
        console.log('📊 Enviando para Google Sheets...');
        await fetch(GOOGLE_SHEETS_SCRIPT_URL, {
          method: 'POST',
          mode: 'no-cors',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            date: selectedSlot.toLocaleDateString('pt-BR'),
            time: selectedSlot.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
            name: info.name,
            school: info.school,
            email: info.email,
            whatsapp: info.whatsapp,
            timestamp: new Date().toISOString()
          })
        });
        console.log('✅ Enviado para Google Sheets');
      } catch (error) {
        console.error("❌ Erro ao enviar para Google Sheets:", error);
      }
    }

    if (window.emailjs && EMAILJS_SERVICE_ID) {
      try {
        console.log('📧 Enviando emails...');

        // Formatar datas no formato que funcionava antes
        const year = selectedSlot.getFullYear();
        const month = String(selectedSlot.getMonth() + 1).padStart(2, '0');
        const day = String(selectedSlot.getDate()).padStart(2, '0');
        const hours = String(selectedSlot.getHours()).padStart(2, '0');
        const minutes = String(selectedSlot.getMinutes()).padStart(2, '0');

        const dateStart = `${year}${month}${day}T${hours}${minutes}00`;

        const endSlot = new Date(selectedSlot.getTime() + 30 * 60000);
        const endYear = endSlot.getFullYear();
        const endMonth = String(endSlot.getMonth() + 1).padStart(2, '0');
        const endDay = String(endSlot.getDate()).padStart(2, '0');
        const endHours = String(endSlot.getHours()).padStart(2, '0');
        const endMinutes = String(endSlot.getMinutes()).padStart(2, '0');
        const dateEnd = `${endYear}${endMonth}${endDay}T${endHours}${endMinutes}00`;

        console.log('🔍 DEBUG - Dados que serão enviados:');
        console.log('date_start:', dateStart);
        console.log('date_end:', dateEnd);
        console.log('date:', selectedSlot.toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }));
        console.log('time:', selectedSlot.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }));

        const emailParams = {
          name: info.name,
          school: info.school,
          email: info.email,
          whatsapp: info.whatsapp,
          date: selectedSlot.toLocaleDateString('pt-BR', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' }),
          time: selectedSlot.toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }),
          date_start: dateStart,
          date_end: dateEnd
        };

        console.log('📦 Parâmetros completos:', emailParams);

        const result1 = await window.emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, emailParams);
        console.log('✅ Email enviado para administrador - Status:', result1.status, result1.text);

        const result2 = await window.emailjs.send(EMAILJS_SERVICE_ID, EMAILJS_CLIENT_TEMPLATE_ID, emailParams);
        console.log('✅ Email enviado para cliente - Status:', result2.status, result2.text);
      } catch (error) {
        console.error("❌ Erro DETALHADO ao enviar emails:", error);
        console.error("Mensagem:", error.message);
        console.error("Stack:", error.stack);
      }
    } else {
      console.error('❌ EmailJS não está carregado ou SERVICE_ID está vazio');
    }

    setConfirmedEvent({ clientInfo: info, date: selectedSlot });
    setIsLoading(false);
  };

  const resetBooking = () => {
    setConfirmedEvent(null);
    setSelectedSlot(null);
    handleDateChange(selectedDate);
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-50 to-green-50 flex flex-col">
      <Header />
      <main className="flex-grow container mx-auto p-4 md:p-8">
        <div className="max-w-5xl mx-auto bg-white rounded-3xl shadow-2xl overflow-hidden p-8 md:p-12">
          {confirmedEvent ? (
            <Confirmation event={confirmedEvent} onNew={resetBooking} />
          ) : selectedSlot ? (
            <BookingForm selectedSlot={selectedSlot} onBook={handleBook} onBack={() => setSelectedSlot(null)} />
          ) : (
            <div>
              <div className="text-center mb-12">
                <h2 className="text-4xl md:text-5xl font-bold text-gray-800 mb-3">
                  Agende com a <span className="text-green-700">Patitour</span>
                </h2>
                <p className="text-gray-600 text-lg">
                  Escolha o melhor horário para seu atendimento personalizado com nossa equipe.
                </p>
              </div>
              {selectedDate && <DateSelector selectedDate={selectedDate} onDateChange={handleDateChange} />}
              {selectedDate && <TimeSlots slots={availableSlots} onSlotSelect={setSelectedSlot} isLoading={isLoading} />}
            </div>
          )}
        </div>
      </main>
      <footer className="text-center py-6 text-gray-400 text-sm">
        © {new Date().getFullYear()} Patitour • Turismo Pedagógico e Experiências
      </footer>
    </div>
  );
}

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);


